# Surah Ar-Ra'd (chapter 13) — part 1: ayat 1-10 (IDs 1708-1717)
SURAH = 13

ENTRIES = {
1708: (
"المر — یہ کتاب کی آیتیں ہیں — اور جو آپ کی طرف آپ کے رب کی جانب سے نازل کیا گیا ہے — وہ حق ہے — لیکن اکثر لوگ ایمان نہیں لاتے",
"""۱۔ سورہ کا آغاز حروفِ مقطعات کے ساتھ؛ قرآن حق ہے؛ اکثر لوگ ایمان نہیں لاتے۔
۲۔ ’’المر تِلْكَ آيَاتُ الْكِتَابِ وَالَّذِي أُنزِلَ إِلَيْكَ مِن رَّبِّكَ الْحَقُّ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ‘‘ — المر — یہ کتاب کی آیتیں ہیں — اور جو آپ کی طرف آپ کے رب کی جانب سے نازل کیا گیا ہے — وہ حق ہے — لیکن اکثر لوگ ایمان نہیں لاتے — یعنی المر — یہ کتاب کی آیتیں ہیں — اور جو آپ کی طرف آپ کے رب کی جانب سے نازل کیا گیا ہے وہ حق ہے — لیکن اکثر لوگ ایمان نہیں لاتے۔
۳۔ عملی سبق: قرآن کو ماننا — ہر حق کا معیار ہے؛ جہاں تک ممکن ہو اس کے مطابق زندگی گزاریں۔"""
),
1709: (
"اللہ ہے جس نے آسمانوں کو — بغیر ستونوں کے اٹھایا — جنہیں تم دیکھتے ہو — پھر وہ عرش پر قائم ہوا — اور سورج اور چاند کو تابع کر دیا — سب ایک مقررہ وقت کی طرف چل رہے ہیں — وہ معاملے کی تدبیر کرتا ہے — آیتیں کھول کر بیان کرتا ہے — تاکہ تم اپنے رب سے ملاقات کا یقین کرو",
"""۱۔ کائنات کی ابتداء اور نظام — بغیر ستونوں کے آسمان؛ سورج و چاند کی تابع داری؛ ہر چیز کا معین وقت۔
۲۔ ’’اللَّهُ الَّذِي رَفَعَ السَّمَاوَاتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى يُدَبِّرُ الْأَمْرَ يُفَصِّلُ الْآيَاتِ لَعَلَّكُم بِلِقَاءِ رَبِّكُمْ تُوقِنُونَ‘‘ — اللہ ہے جس نے آسمانوں کو — بغیر ستونوں کے اٹھایا — جنہیں تم دیکھتے ہو — پھر وہ عرش پر قائم ہوا — اور سورج اور چاند کو تابع کر دیا — سب ایک مقررہ وقت کی طرف چل رہے ہیں — وہ معاملے کی تدبیر کرتا ہے — آیتیں کھول کر بیان کرتا ہے — تاکہ تم اپنے رب سے ملاقات کا یقین کرو — یعنی اللہ ہی ہے جس نے آسمانوں کو بغیر ستونوں کے اٹھایا — جنہیں تم دیکھتے ہو — پھر وہ عرش پر قائم ہوا — اور سورج اور چاند کو تابع کر دیا — سب ایک مقررہ وقت تک چل رہے ہیں — وہ معاملے کی تدبیر کرتا ہے — آیتیں تفصیل سے بیان کرتا ہے — تاکہ تم اپنے رب سے ملاقات کا یقین کرو۔
۳۔ عملی سبق: کائنات کی ترتیب سے سبق لیجیے؛ قیامت پر ایمان — ہر مسلمان کی شرطِ نجات ہے۔"""
),
1710: (
"اور وہی ہے جس نے زمین کو پھیلایا اور اس میں پہاڑوں کو مضبوط کر دیا اور نہریں بہائیں — اور ہر طرح کے پھلوں میں سے دو دو قسمیں بنائیں — وہ رات کو دن پر چھا دیتا ہے — یقیناً اس میں غور و فکر کرنے والوں کے لیے نشانیاں ہیں",
"""۱۔ زمین کا پھیلاؤ — پہاڑ — نہریں — پھلوں کی جوڑی — رات دن کی گردش — یہ سب دلائل ہیں۔
۲۔ ’’وَهُوَ الَّذِي مَدَّ الْأَرْضَ وَجَعَلَ فِيهَا رَوَاسِيَ وَأَنْهَارًا وَمِن كُلِّ الثَّمَرَاتِ جَعَلَ فِيهَا زَوْجَيْنِ اثْنَيْنِ يُغْشِي اللَّيْلَ النَّهَارَ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يَتَفَكَّرُونَ‘‘ — اور وہی ہے جس نے زمین کو پھیلایا اور اس میں پہاڑوں کو مضبوط کر دیا اور نہریں بہائیں — اور ہر طرح کے پھلوں میں سے دو دو قسمیں بنائیں — وہ رات کو دن پر چھا دیتا ہے — یقیناً اس میں غور و فکر کرنے والوں کے لیے نشانیاں ہیں — یعنی وہی ہے جس نے زمین کو پھیلایا — اور اس میں پہاڑوں کو مضبوط کر دیا اور نہریں بہائیں — اور ہر قسم کے پھلوں میں سے دو دو قسمیں بنائیں — وہ رات کو دن پر چھا دیتا ہے — یقیناً اس میں غور و فکر کرنے والوں کے لیے نشانیاں ہیں۔
۳۔ عملی سبق: فطرت کی ہر چیز اللہ کی نشانی ہے؛ چشمِ بصیرت سے دیکھیں۔"""
),
1711: (
"اور زمین میں ایک دوسرے سے ملحق قطعات ہیں اور انگور کے باغات اور کھیتیاں اور کھجوریں جو ایک ہی تنے سے پھوٹتی ہیں اور جو الگ الگ ہیں — ایک ہی پانی سے سیراب کی جاتی ہیں — اور ہم ان میں سے بعض کو کھانے میں فضیلت دیتے ہیں — یقیناً اس میں عقل رکھنے والوں کے لیے نشانیاں ہیں",
"""۱۔ ایک ہی زمین، ایک ہی پانی — مگر ذائقہ مختلف؛ اللہ کی قدرت پر دلالت۔
۲۔ ’’وَفِي الْأَرْضِ قِطَعٌ مُّتَجَاوِرَاتٌ وَجَنَّاتٌ مِّنْ أَعْنَابٍ وَزَرْعٌ وَنَخِيلٌ صِنْوَانٌ وَغَيْرُ صِنْوَانٍ يُسْقَىٰ بِمَاءٍ وَاحِدٍ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضٍ فِي الْأُكُلِ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّقَوْمٍ يَعْقِلُونَ‘‘ — اور زمین میں ایک دوسرے سے ملحق قطعات ہیں اور انگور کے باغات اور کھیتیاں اور کھجوریں جو ایک ہی تنے سے پھوٹتی ہیں اور جو الگ الگ ہیں — ایک ہی پانی سے سیراب کی جاتی ہیں — اور ہم ان میں سے بعض کو کھانے میں فضیلت دیتے ہیں — یقیناً اس میں عقل رکھنے والوں کے لیے نشانیاں ہیں — یعنی زمین میں ایک دوسرے سے ملحق اور متوازی قطعات ہیں — اور انگور کے باغات اور کھیتیاں اور کھجوریں — ایک ہی تنے سے پھوٹتی ہیں اور کچھ الگ الگ — ایک ہی پانی سے سیراب کی جاتی ہیں — اور ہم بعض کو کھانے میں فضیلت دیتے ہیں — یقیناً اس میں عقل رکھنے والوں کے لیے نشانیاں ہیں۔
۳۔ عملی سبق: ہر نعمت پر اللہ کا شکر — اور اپنی محنت کو نعمت کا ذریعہ سمجھیں۔"""
),
1712: (
"اور اگر آپ کو تعجب آتا ہے تو ان کا یہ قول تعجب خیز ہے کہ جب ہم مٹی بن گئے تو کیا واقعی ہم نئے سرے سے پیدا کیے جائیں گے — یہی وہ لوگ ہیں جنہوں نے اپنے رب سے انکار کیا — اور یہی لوگ ہیں جن کی گردنوں میں طوق ہوگا — اور یہی لوگ جہنم والے ہیں — وہ اس میں ہمیشہ رہنے والے ہیں",
"""۱۔ قیامت کے منکرین کا انجام بیان کیا گیا؛ کوئی شک کی گنجائش نہیں۔
۲۔ ’’وَإِن تَعْجَبْ فَعَجَبٌ قَوْلُهُمْ أَإِذَا كُنَّا تُرَابًا أَإِنَّا لَفِي خَلْقٍ جَدِيدٍ أُولَٰئِكَ الَّذِينَ كَفَرُوا بِرَبِّهِمْ وَأُولَٰئِكَ الْأَغْلَالُ فِي أَعْنَاقِهِمْ وَأُولَٰئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ‘‘ — اور اگر آپ کو تعجب آتا ہے تو ان کا یہ قول تعجب خیز ہے کہ جب ہم مٹی بن گئے تو کیا واقعی ہم نئے سرے سے پیدا کیے جائیں گے — یہی وہ لوگ ہیں جنہوں نے اپنے رب سے انکار کیا — اور یہی لوگ ہیں جن کی گردنوں میں طوق ہوگا — اور یہی لوگ جہنم والے ہیں — وہ اس میں ہمیشہ رہنے والے ہیں — یعنی اگر آپ کو تعجب کرنا ہے تو ان کا یہ قول تعجب خیز ہے — کہ جب ہم مٹی بن جائیں تو کیا واقعی نئے سرے سے پیدا کیے جائیں گے — یہی وہ لوگ ہیں جنہوں نے اپنے رب کا انکار کیا — اور یہی لوگ ہیں جن کی گردنوں میں طوق ہوں گے — اور یہی لوگ جہنم والے ہیں — وہ اس میں ہمیشہ رہنے والے ہیں۔
۳۔ عملی سبق: قیامت پر یقین — ایمان کا اہم حصہ ہے؛ دنیا کی بے فکری ترک کریں۔"""
),
1713: (
"اور وہ آپ سے نیکی سے پہلے برائی کے جلد آنے کا تقاضا کرتے ہیں — حالانکہ ان سے پہلے بڑی بڑی عبرتیں گزر چکی ہیں — یقیناً آپ کا رب لوگوں کے لیے ان کے ظلم کے باوجود بڑا مغفرت کرنے والا ہے — اور یقیناً آپ کا رب بہت سخت سزا دینے والا ہے",
"""۱۔ مشرکین کی زبردستی مانگ؛ اللہ کی مغفرت اور سخت سزا کا بیان۔
۲۔ ’’وَيَسْتَعْجِلُونَكَ بِالسَّيِّئَۃِ قَبْلَ الْحَسَنَۃِ وَقَدْ خَلَتْ مِن قَبْلِهِمُ الْمَثُلَاتُ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَۃٍ لِّلنَّاسِ عَلَىٰ ظُلْمِهِمْ وَإِنَّ رَبَّكَ لَشَدِيدُ الْعِقَابِ‘‘ — اور وہ آپ سے نیکی سے پہلے برائی کے جلد آنے کا تقاضا کرتے ہیں — حالانکہ ان سے پہلے بڑی بڑی عبرتیں گزر چکی ہیں — یقیناً آپ کا رب لوگوں کے لیے ان کے ظلم کے باوجود بڑا مغفرت کرنے والا ہے — اور یقیناً آپ کا رب بہت سخت سزا دینے والا ہے — یعنی وہ آپ سے برائی کے جلد آنے کا تقاضا کرتے ہیں نیکی سے پہلے — حالانکہ ان سے پہلے بڑی بڑی عبرتیں گزر چکی ہیں — یقیناً آپ کا رب لوگوں کے لیے ان کے ظلم پر مغفرت کرنے والا ہے — اور یقیناً آپ کا رب سخت سزا دینے والا ہے۔
۳۔ عملی سبق: اللہ کی مغفرت پر بھروسہ رکھیں — مگر اس کی گرفت سے بھی ڈریں؛ گناہ مفت میں نہ کریں۔"""
),
1714: (
"اور وہ لوگ جنہوں نے انکار کیا کہتے ہیں اس پر اس کے رب کی طرف سے کوئی نشانی کیوں نہیں اتری — آپ تو صرف ڈرانے والے ہیں — اور ہر قوم کے لیے ایک رہنما ہے",
"""۱۔ ہر قوم کے لیے ہادی؛ یقیناً یہ ہدایت ضرور ملتی ہے؛ آپ کے ذمہ صرف ڈرانا ہے۔
۲۔ ’’وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَۃٌ مِّن رَّبِّهِ إِنَّمَا أَنتَ مُنذِرٌ وَلِكُلِّ قَوْمٍ هَادٍ‘‘ — اور وہ لوگ جنہوں نے انکار کیا کہتے ہیں اس پر اس کے رب کی طرف سے کوئی نشانی کیوں نہیں اتری — آپ تو صرف ڈرانے والے ہیں — اور ہر قوم کے لیے ایک رہنما ہے — یعنی کافر کہتے ہیں — اس پر اس کے رب کی طرف سے کوئی واضح نشانی کیوں نازل نہیں کی گئی — آپ تو صرف ڈرانے والے ہیں — اور ہر قوم کے لیے ایک ہادی ہے۔
۳۔ عملی سبق: ہر دور میں رہنمائی کا سلسلہ قائم رہا؛ نبی اکرم ﷺ کے بعد ائمہ اہل بیتؑ ہدايت کے دروازے ہیں۔"""
),
1715: (
"اللہ جانتا ہے کہ ہر ماں کے پیٹ میں کیا ہے — اور جو بچہ پیٹ میں کم ہوتا اور جو بڑھتا ہے — اور ہر چیز اس کے پاس ایک منصوبے کے ساتھ ہے",
"""۱۔ اللہ کا علم لازوال؛ ماں کے پیٹ کی ہر حالت اس کو معلوم؛ ہر چیز کا تقدیر کا منصوبہ۔
۲۔ ’’اللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ الْأَرْحَامُ وَمَا تَزْدَادُ وَكُلُّ شَيْءٍ عِندَهُ بِمِقْدَارٍ‘‘ — اللہ جانتا ہے کہ ہر ماں کے پیٹ میں کیا ہے — اور جو بچہ پیٹ میں کم ہوتا اور جو بڑھتا ہے — اور ہر چیز اس کے پاس ایک منصوبے کے ساتھ ہے — یعنی اللہ جانتا ہے کہ ہر ماں کے پیٹ میں کیا ہے — اور جو بچہ پیٹ میں کم ہوتا ہے اور جو بڑھتا ہے — اور ہر چیز اس کے ہاں ایک منصوبہ کے مطابق ہے۔
۳۔ عملی سبق: اللہ کے علم پر بھروسہ رکھیں؛ زندگی کا ہر لمحہ اللہ کے منصوبے میں ہے۔"""
),
1716: (
"وہ غیب اور حاضر کا جاننے والا ہے — بڑا اور بلند و برتر ہے",
"""۱۔ اللہ عالم الغیب و الشہادہ — کبریائی اور رفعت کا مالک۔
۲۔ ’’عَالِمُ الْغَيْبِ وَالشَّهَادَۃِ الْكَبِيرُ الْمُتَعَالِ‘‘ —وہ غیب اور حاضر کا جاننے والا ہے — بڑا اور بلند و برتر ہے۔
۳۔ عملی سبق: اللہ سے ڈرنا چاہیے؛ وہ ہماری ہر پوشیدہ بات جانتا ہے۔"""
),
1717: (
"تم میں سے جو پوشیدہ بات کرے یا بلند آواز سے کہے — اور جو رات میں چھپا رہتا ہے اور دن میں چلتا ہے — سب اللہ کے لیے برابر ہیں",
"""۱۔ اللہ کا علم ہر گوشے میں ہے — چھپ کر بھی ہو یا سب کے سامنے۔
۲۔ ’’سَوَاءٌ مِّنكُم مَّنْ أَسَرَّ الْقَوْلَ وَمَن جَهَرَ بِهِ وَمَنْ هُوَ مُسْتَخْفٍ بِاللَّيْلِ وَسَارِبٌ بِالنَّهَارِ‘‘ — تم میں سے جو پوشیدہ بات کرے یا بلند آواز سے کہے — اور جو رات میں چھپا رہتا ہے اور دن میں چلتا ہے — سب اللہ کے لیے برابر ہیں — یعنی تم میں سے جو پوشیدہ بات کرتا ہے یا بلند آواز سے کرتا ہے — اور جو رات میں چھپا رہتا ہے اور دن میں چلتا ہے — سب اللہ کے ہاں برابر ہیں۔
۳۔ عملی سبق: اکیلے میں بھی اللہ کی نگرانی میں ہیں؛ گناہ اکیلے میں بھی نہ کرو۔"""
),
}
